async function handleOrder(order, db, payments) {
  const existing = await db.findOrder(order.id);
  if (existing) return existing;

  const charge = await payments.charge(order.total);
  const saved = await db.saveOrder({ id: order.id, chargeId: charge.id });
  return saved;
}

